-- Votos de PRESIDENTE por local de votacao (PA), turnos 1 e 2.
-- Fonte: TSE dadosabertos votacao_secao_2026_BR (gerado 26/10/2026).
-- Idempotente: apaga o que for de presidente 2026 antes de inserir.

DELETE FROM VotoLocal WHERE candidatoId LIKE 'c26p-%';

DROP TABLE IF EXISTS _vl_pres;
CREATE TEMPORARY TABLE _vl_pres (chave TEXT, numero INTEGER, turno INTEGER, votos INTEGER);


SELECT 'c26p-' || p.numero, ce.id, p.turno, p.votos
FROM _vl_pres p
JOIN ColegioEleitoral ce ON ce.codigoTse = p.chave;

DROP TABLE _vl_pres;
